(function(global){"use strict";const RiskRewardEngine={VERSION:"0.1.0",CONFIG:{WEIGHT_LONG:.85,WEIGHT_SESSION:.15,K_LONG:.06,K_SESSION:.18,K_ITEM:.015,DEFAULT_BASE_GOLD:20},CHALLENGE_TABLE:[{min:.9,max:1.01,multiplier:.8,label:"过于简单",tag:"easy"},{min:.8,max:.9,multiplier:1,label:"轻松生还",tag:"light"},{min:.65,max:.8,multiplier:1.3,label:"最佳挑战区",tag:"optimal"},{min:.5,max:.65,multiplier:1.5,label:"高挑战区（黄金心流）",tag:"peak"},{min:.35,max:.5,multiplier:1.35,label:"接近能力边界",tag:"boundary"},{min:0,max:.35,multiplier:1,label:"疑似超纲/猜测区",tag:"out_of_bounds"}],CONFIDENCE_TABLE:[{minAnswer:200,confidence:1},{minAnswer:100,confidence:.85},{minAnswer:50,confidence:.7},{minAnswer:20,confidence:.45},{minAnswer:0,confidence:.2}],createInitialProfile(){return{theta_long:0,theta_session:0,answer_count:0,vocab_rating:0}},calculateEffectiveAbility(thetaLong,thetaSession,weightLong){const wL=typeof weightLong==="number"?weightLong:this.CONFIG.WEIGHT_LONG;const wS=1-wL;return wL*thetaLong+wS*thetaSession},calculateActualDifficulty(item){const base=Number(item.base_difficulty)||0;const distractor=Number(item.distractor_difficulty)||0;const context=Number(item.context_difficulty)||0;const mode=Number(item.mode_difficulty)||0;const empirical=Number(item.empirical_offset)||0;return base+distractor+context+mode+empirical},predictPCorrect(thetaEffective,dActual){const diff=thetaEffective-dActual;if(diff>15)return.99999;if(diff<-15)return 1e-5;return 1/(1+Math.exp(-diff))},getChallengeTier(pCorrect){const p=Math.max(0,Math.min(1,pCorrect));for(const tier of this.CHALLENGE_TABLE){if(p>=tier.min&&p<tier.max){return tier}}return this.CHALLENGE_TABLE[this.CHALLENGE_TABLE.length-1]},getConfidence(answerCount){const count=Math.max(0,parseInt(answerCount,10)||0);for(const row of this.CONFIDENCE_TABLE){if(count>=row.minAnswer){return row.confidence}}return.2},calculateFinalMultiplier(mChallenge,confidence){const conf=Math.max(0,Math.min(1,confidence));return 1+conf*(mChallenge-1)},getSanDistractorDifficulty(san){const s=typeof san==="number"?san:100;if(s>=80)return 0;if(s>=50)return.15;if(s>=30)return.25;return.35},checkSafetyRails(pCorrect){if(pCorrect>=.8){return{allowHarder:true,fallback:false,zone:"easy",note:"允许继续增加干扰度或复杂语境"}}if(pCorrect>=.55){return{allowHarder:false,fallback:false,zone:"optimal",note:"保持当前心流挑战"}}if(pCorrect>=.35){return{allowHarder:false,fallback:false,zone:"boundary",note:"能力边界：保留视觉氛围，锁死语言难度"}}return{allowHarder:false,fallback:true,zone:"fallback",note:"触发护栏：语言难度过高，应退回提示或降低干扰相似度"}},estimateBaseDifficulty(word,tierDict){if(!word)return 0;const w=String(word).toLowerCase().trim();const tier=tierDict&&tierDict[w]?tierDict[w]:"cet4";if(tier==="cet4")return 0;if(tier==="cet6")return.35;if(tier==="ielts")return.7;return.2},evaluateQuestion(profile,itemInput){const pData=profile||this.createInitialProfile();const thetaLong=Number(pData.theta_long)||0;const thetaSession=Number(pData.session_state??pData.theta_session)||0;const answerCount=parseInt(pData.answer_count,10)||0;const thetaEff=this.calculateEffectiveAbility(thetaLong,thetaSession);const dActual=this.calculateActualDifficulty(itemInput);const pCorrect=this.predictPCorrect(thetaEff,dActual);const tier=this.getChallengeTier(pCorrect);const confidence=this.getConfidence(answerCount);const mFinal=this.calculateFinalMultiplier(tier.multiplier,confidence);const baseGold=Number(itemInput.base_gold)||this.CONFIG.DEFAULT_BASE_GOLD;const finalReward=Math.round(baseGold*mFinal*10)/10;const safety=this.checkSafetyRails(pCorrect);return{theta_long:thetaLong,theta_session:thetaSession,theta_effective:thetaEff,d_actual:dActual,p_correct:pCorrect,challenge_tier:tier.label,challenge_tag:tier.tag,m_challenge:tier.multiplier,confidence:confidence,m_final:mFinal,base_gold:baseGold,final_reward:finalReward,safety_rails:safety}},updateState(profile,item,isSuccess,evalResult,options={}){const y=isSuccess?1:0;const p=evalResult?evalResult.p_correct:.5;const residual=y-p;const kLong=options.kLong||this.CONFIG.K_LONG;const kSession=options.kSession||this.CONFIG.K_SESSION;const kItem=options.kItem||this.CONFIG.K_ITEM;const newThetaLong=(Number(profile.theta_long)||0)+kLong*residual;const newThetaSession=(Number(profile.session_state??profile.theta_session)||0)+kSession*residual;const newAnswerCount=(parseInt(profile.answer_count,10)||0)+1;let newEmpirical=Number(item.empirical_offset)||0;newEmpirical=newEmpirical-kItem*residual;return{profile_update:{theta_long:Math.round(newThetaLong*1e4)/1e4,theta_session:Math.round(newThetaSession*1e4)/1e4,session_state:Math.round(newThetaSession*1e4)/1e4,answer_count:newAnswerCount,confidence:this.getConfidence(newAnswerCount)},item_update:{empirical_offset:Math.round(newEmpirical*1e4)/1e4},residual:residual}}};if(typeof module!=="undefined"&&module.exports){module.exports=RiskRewardEngine}if(typeof window!=="undefined"){window.RiskRewardEngine=RiskRewardEngine}})(typeof globalThis!=="undefined"?globalThis:this);